# Generated by build.py from recipe.yml for recipe sftp-upload-with-a-read-callback. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'mkdir -p store'
cmd /c 'ssh-keygen -q -t rsa -b 3072 -N "" -f host_key'
cmd /c 'ssh-keygen -q -t rsa -b 3072 -N "" -f other_key'
cmd /c 'sh pin.sh host_key.pub > pin.txt'
cmd /c 'head -c 300000 /dev/urandom > report.bin'
$server0 = Start-Process surl -ArgumentList '--hostkey', 'host_key', '--user', 'alice:s3cret', '--allow-uploads', '--directory', 'store', 'sftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { dotnet run upload.cs -- sftp://127.0.0.1:8080/report.bin alice:s3cret report.bin pin.txt } finally { Stop-Process $server0 }
